class TestLogAndMetricException:
    """Validate exception logging and counter increment behavior."""

    def test_logs_error_with_exception_info(self, mock_logger, mock_counter):
        """Verify error is logged with exc_info=True and formatted message."""
        exc = ValueError("boom")
        log_and_metric_exception(mock_logger, mock_counter, exc, "Processing failed")

        mock_logger.error.assert_called_once_with(
            "Processing failed: boom", exc_info=True
        )

    def test_increments_counter(self, mock_logger, mock_counter):
        """Verify counter .inc() is called exactly once."""
        log_and_metric_exception(
            mock_logger, mock_counter, RuntimeError("x"), "Failure"
        )
        mock_counter.inc.assert_called_once_with()

    def test_forwards_extra_kwargs_to_logger(self, mock_logger, mock_counter):
        """Verify additional kwargs are passed to logger.error."""
        log_and_metric_exception(
            mock_logger,
            mock_counter,
            ValueError("bad"),
            "Error",
            extra={"request_id": "abc123"},
        )
        mock_logger.error.assert_called_once_with(
            "Error: bad", exc_info=True, extra={"request_id": "abc123"}
        )

    def test_empty_message(self, mock_logger, mock_counter):
        """Verify empty message string is handled gracefully."""
        exc = Exception("detail")
        log_and_metric_exception(mock_logger, mock_counter, exc, "")
        mock_logger.error.assert_called_once_with(": detail", exc_info=True)

    def test_exception_with_no_message(self, mock_logger, mock_counter):
        """Verify exception with empty str() representation."""
        class SilentError(Exception):
            def __str__(self):
                return ""

        exc = SilentError()
        log_and_metric_exception(mock_logger, mock_counter, exc, "Silent")
        mock_logger.error.assert_called_once_with("Silent: ", exc_info=True)

    def test_counter_increment_after_logging(self, mock_logger, mock_counter):
        """Verify order: log first, then increment (deterministic behavior)."""
        log_and_metric_exception(
            mock_logger, mock_counter, ValueError("e"), "Order"
        )
        # Assert call order
        assert mock_logger.error.call_count == 1
        assert mock_counter.inc.call_count == 1
        # Ensure logger.error was called before counter.inc
        logger_call_time = mock_logger.error.call_args
        counter_call_time = mock_counter.inc.call_args
        # In Mock, call order can be checked via call_args_list order
        assert mock_logger.method_calls[0][0] == "error"
        assert mock_counter.method_calls[0][0] == "inc"


