# get_breaker_state_value
# -----------------------------------------------------------------------------
class TestGetBreakerStateValue:
    """Validate circuit breaker state string to integer mapping."""

    @pytest.mark.parametrize(
        "state,expected",
        [
            ("closed", 0),
            ("open", 1),
            ("half-open", 2),
        ],
    )
    def test_valid_states(self, state, expected):
        """Verify known pybreaker states map to correct integers."""
        assert get_breaker_state_value(state) == expected

    @pytest.mark.parametrize(
        "invalid_state",
        [
            "CLOSED",       # case sensitivity
            "Closed",       # mixed case
            "half_open",    # underscore instead of hyphen
            "unknown",
            "",
            None,
            0,
            1.5,
            ["closed"],
            {"state": "open"},
        ],
    )
    def test_invalid_states_return_minus_one(self, invalid_state):
        """Verify any unrecognized input returns -1."""
        assert get_breaker_state_value(invalid_state) == -1

    def test_whitespace_not_trimmed(self):
        """Verify leading/trailing whitespace is not accepted."""
        assert get_breaker_state_value(" closed ") == -1

    def test_returns_int_type(self):
        """Verify return type is always int."""
        for state in ["closed", "open", "half-open", "garbage"]:
            result = get_breaker_state_value(state)
            assert isinstance(result, int)


